@dataclasses.dataclass
class NoteConfig:
    # AISkillAnalysisNote provides the metadata of an AI-based skill analysis.
    ai_skill_analysis: Any = None
    # Note kind that represents a logical attestation "role" or "authority". For example, an organization might have one `Authority` for "QA" and one for "build". This note is intended to act strictly as a grouping mechanism for the attached occurrences (Attestations). This grouping mechanism also provides a security boundary, since IAM ACLs gate the ability for a principle to attach an occurrence to a given note. It also provides a single point of lookup to find all attached attestation occurrences, even if they don't all live in the same project.
    attestation: Any = None
    # Note holding the version of the provider's builder and the signature of the provenance message in the build details occurrence.
    build: Any = None
    compliance: Any = None
    # Output only. The time this note was created. This field can be used as a filter in list requests.
    create_time: Any = None
    # An artifact that can be deployed in some runtime.
    deployment: Any = None
    # A note that indicates a type of analysis a provider would perform. This note exists in a provider's project. A `Discovery` occurrence is created in a consumer's project at the start of analysis.
    discovery: Any = None
    dsse_attestation: Any = None
    # Time of expiration for this note. Empty if note does not expire.
    expiration_time: Any = None
    # Basis describes the base image portion (Note) of the DockerImage relationship. Linked occurrences are derived from this or an equivalent image via: FROM Or an equivalent reference, e.g., a tag of the resource_url.
    image: Any = None
    # Output only. The type of analysis. This field can be used as a filter in list requests.
    kind: Any = None
    # A detailed description of this note.
    long_description: Any = None
    # Output only. The name of the note in the form of `projects/[PROVIDER_ID]/notes/[NOTE_ID]`.
    name: Any = None
    # PackageNote represents a particular package version.
    package: Any = None
    # Other notes related to this note.
    related_note_names: Any = None
    # URLs associated with this note.
    related_url: Any = None
    # The note representing an SBOM reference.
    sbom_reference: Any = None
    # The note representing a secret.
    secret: Any = None
    # A one sentence description of this note.
    short_description: Any = None
    # Output only. The time this note was last updated. This field can be used as a filter in list requests.
    update_time: Any = None
    # An Upgrade Note represents a potential upgrade of a package to a given version. For each package version combination (i.e. bash 4.0, bash 4.1, bash 4.1.2), there will be an Upgrade Note. For Windows, windows_update field represents the information related to the update.
    upgrade: Any = None
    # A security vulnerability that can be found in resources.
    vulnerability: Any = None
    # A single VulnerabilityAssessmentNote represents one particular product's vulnerability assessment for one CVE.
    vulnerability_assessment: Any = None

